pulse_glow.glsl:
shader_type canvas_item;

uniform float glow_intensity : hint_range(0.0, 3.0) = 1.5;
uniform float pulse_speed : hint_range(0.0, 10.0) = 2.0;
uniform vec4 glow_color : source_color = vec4(0.3, 0.6, 1.0, 1.0);

void fragment() {
	vec4 tex = texture(TEXTURE, UV);
	float pulse = (sin(TIME * pulse_speed) * 0.5 + 0.5) * glow_intensity;
	vec3 glow = glow_color.rgb * pulse;
	COLOR = vec4(tex.rgb + glow * tex.a, tex.a);
}

dissolve.glsl:
shader_type canvas_item;

uniform float dissolve_amount : hint_range(0.0, 1.0) = 0.0;
uniform float edge_width : hint_range(0.0, 0.2) = 0.05;
uniform vec4 edge_color : source_color = vec4(1.0, 0.5, 0.0, 1.0);
uniform float noise_scale : hint_range(1.0, 20.0) = 8.0;

float hash(vec2 p) {
	return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
	vec2 i = floor(p);
	vec2 f = fract(p);
	f = f * f * (3.0 - 2.0 * f);
	float a = hash(i);
	float b = hash(i + vec2(1.0, 0.0));
	float c = hash(i + vec2(0.0, 1.0));
	float d = hash(i + vec2(1.0, 1.0));
	return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

void fragment() {
	vec4 tex = texture(TEXTURE, UV);
	float n = noise(UV * noise_scale);
	float dissolve_val = (sin(TIME * 0.8) * 0.5 + 0.5);
	float alpha = step(dissolve_val, n);
	float edge = step(dissolve_val - edge_width, n) - alpha;
	vec3 col = mix(tex.rgb, edge_color.rgb, edge);
	COLOR = vec4(col, tex.a * alpha + edge * tex.a);
}

holographic.glsl:
shader_type canvas_item;

uniform float scan_speed : hint_range(0.0, 5.0) = 1.0;
uniform float scan_line_count : hint_range(10.0, 100.0) = 40.0;
uniform float color_shift_speed : hint_range(0.0, 5.0) = 0.5;
uniform float hologram_alpha : hint_range(0.0, 1.0) = 0.8;

vec3 hsv2rgb(vec3 c) {
	vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
	vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
	return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void fragment() {
	vec4 tex = texture(TEXTURE, UV);
	float scan = sin((UV.y + TIME * scan_speed) * scan_line_count * 3.14159) * 0.5 + 0.5;
	float hue = fract(UV.y * 0.5 + TIME * color_shift_speed);
	vec3 holo_color = hsv2rgb(vec3(hue, 0.7, 1.0));
	vec3 result = mix(tex.rgb, holo_color, 0.6) * (0.8 + 0.2 * scan);
	COLOR = vec4(result, tex.a * hologram_alpha);
}
